function dueCap() {
  return nextEvent(localIsoDay(0))?.start ?? "";
}
function capDue(iso) {
  const cap = dueCap();
  if (!cap || cap <= localIsoDay(0)) return iso;
  return iso > cap ? cap : iso;
}
function computeDue(sonuc, streak, severity) {
  if (sonuc === "wrong") return capDue(localIsoDay(1));
  if (sonuc === "half") return capDue(localIsoDay(severity === "tournament_life" ? 1 : 2));
  const steps = [3, 7, 14, 30];
  const off = steps[Math.min(Math.max(streak, 1) - 1, steps.length - 1)];
  return capDue(localIsoDay(off));
}
function computeMastery(streak, correctDays) {
  const days = new Set(correctDays).size;
  if (streak >= 3 && days >= 3) return "saglam";
  if (streak >= 2 && days >= 2) return "yetkin";
  if (streak >= 1) return "asina";
  return "gorundu";
}
function fresh(kavram, base) {
  return {
    id: kavram,
    kavram,
    soru_ozeti: "",
    sonuc: "wrong",
    streak: 0,
    reps: 0,
    correctDays: [],
    tarih: localIsoDay(0),
    due: localIsoDay(0),
    mastery: "gorundu",
    ...base
  };
}
function migrate(rows) {
  const byK = /* @__PURE__ */ new Map();
  for (const r of rows) {
    const kavram = String(r.kavram || "k\xF6k-hata");
    const cur = byK.get(kavram) || fresh(kavram);
    cur.reps += 1;
    cur.soru_ozeti = String(r.soru_ozeti || cur.soru_ozeti);
    cur.sonuc = r.sonuc || cur.sonuc;
    cur.not = r.not || cur.not;
    cur.tarih = String(r.tarih || cur.tarih);
    cur.due = capDue(String(r.due || cur.due));
    byK.set(kavram, cur);
  }
  return [...byK.values()];
}

